import { onMount } from 'svelte';
export function htmlState(ele) {
    let element = $state(ele);
    const observer = new MutationObserver(([mutation]) => {
        element = null;
        element = mutation.target;
    });
    // observer.observe(ele, { attributes: true })
    onMount(() => {
        observer.observe(ele, { attributes: true });
        return () => {
            observer.disconnect();
        };
    });
    return {
        get ele() {
            return element;
        },
        destroy: () => {
            observer.disconnect();
        },
    };
}
