<script lang="ts" generics="T = unknown">
  import { getPreviewLevel } from '../contexts.js'
  import { getContext } from 'svelte'
  import type { HTMLAttributes } from 'svelte/elements'
  import type { TypeViewProps } from '../types.js'
  import Bullet from './Bullet.svelte'
  import Key from './Key.svelte'
  import Tools from './Tools.svelte'
  import Type from './Type.svelte'

  type Props = TypeViewProps<T> & HTMLAttributes<HTMLDivElement>

  let {
    value,
    display,
    key,
    showKey = true,
    keyDelim = ':',
    keyPrefix,
    keyStyle,
    type,
    forceType,
    path,
    children,
    ...rest
  }: Props = $props()

  let displayOrValue = $derived(display != null ? display : (value?.toString?.() ?? ''))
  let title = $derived(
    typeof value === 'string' ? value : display != null ? display : value?.toString()
  )

  let previewLevel = getPreviewLevel()
  let isKey = getContext<boolean | undefined>('key')
</script>

<div
  data-testid="line"
  class="line"
  class:preview={previewLevel || isKey}
  class:nokey={!showKey}
  {...rest}
>
  <div class="indicator-and-key">
    {#if !previewLevel && !isKey}
      <Bullet {value} />
    {/if}
    {#if showKey}
      <Key disabled prefix={keyPrefix} delim={keyDelim} style={keyStyle} {key} {path} />
    {/if}
  </div>
  {#if !isKey}
    <Type {type} force={forceType} />
  {/if}
  {#if children}
    {@render children()}
  {:else if displayOrValue}
    <span data-testid="value" {title} class="value {type}">
      {displayOrValue}
    </span>
  {/if}

  {#if !previewLevel && !isKey}
    <Tools {value} {path} {type} />
  {/if}
</div>

<style>.line {
  transition: all 0.25s ease-in-out;
  background: linear-gradient(35deg, var(--_hover-color) 60%, transparent 80%);
  background-size: 0% 100%;
  background-origin: border-box;
  background-repeat: no-repeat;
  position: relative;
  display: flex;
  gap: var(--line-gap, 0.5em);
  min-height: 1.5em;
  max-height: 1.5em;
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  padding-left: 0.25em;

  &:hover:not(.preview) {
    background-position-x: left;
    background-size: 100% 100%;
  }
}

.line.preview {
  padding-left: 0;
  margin-left: 0;
}

.line.preview.nokey {
  gap: 0;
}

.indicator-and-key {
  display: inline-flex;
  align-items: center;
  gap: 0.25em;
}
</style>
